(7474769, 1187451, 101256, '<td valign="top">The editing and post processing is absolutely brilliant. A fantasy tale waiting to be told - very ethereal.  Well done.</td>', 'The editing and post processing is absolutely brilliant. A fantasy tale waiting to be told - very ethereal.  Well done.', '2016-09-20 16:41:26.000000', NULL, 1),
(7474770, 1187564, 101256, '<td valign="top">Very intense symbolism here that is hard to put words to. Another interpretative image that displays several emotions depending on the viewer and his/her life experience. Excellent.</td>', 'Very intense symbolism here that is hard to put words to. Another interpretative image that displays several emotions depending on the viewer and his/her life experience. Excellent.', '2016-09-20 16:43:19.000000', NULL, 1),
