(7474772, 1187479, 101256, '<td valign="top">I was trying to decide if this was a composite image, or over sharpened or bitmapped/tonemapped but I can''t quite decide. I like the image very much. Intriguing to say the least.</td>', 'I was trying to decide if this was a composite image, or over sharpened or bitmapped/tonemapped but I can''t quite decide. I like the image very much. Intriguing to say the least.', '2016-09-20 16:46:15.000000', NULL, 1),
(7474773, 1187421, 101256, '<td valign="top">Really enjoy the stick figures - there is so much whimsy, meaning and intent in this image. A terrific composition - well done.</td>', 'Really enjoy the stick figures - there is so much whimsy, meaning and intent in this image. A terrific composition - well done.', '2016-09-20 16:47:26.000000', NULL, 1),
(7474774, 1187283, 101256, '<td valign="top">I''m not exactly sure what the intent here was, but its a heck of an image and for that reason alone (plus its a good technical image) worthy of a 10.</td>', 'I''m not exactly sure what the intent here was, but its a heck of an image and for that reason alone (plus its a good technical image) worthy of a 10.', '2016-09-20 16:48:42.000000', NULL, 1),
(7474775, 1187642, 101256, '<td valign="top">The detail on the owl is incredible and the lighting is perfect.  Not much to say about this - it is the equal of all the other 10 rated imaged in this challenge. Well done.</td>', 'The detail on the owl is incredible and the lighting is perfect.  Not much to say about this - it is the equal of all the other 10 rated imaged in this challenge. Well done.', '2016-09-20 16:49:45.000000', NULL, 1),
(7474776, 1187551, 101256, '<td valign="top">Simple, elegant - simply elegant. Great conversion and a very nice static style still life.  Nicely done.</td>', 'Simple, elegant - simply elegant. Great conversion and a very nice static style still life.  Nicely done.', '2016-09-20 16:50:38.000000', NULL, 1),
(7474777, 1187231, 101256, '<td valign="top">Very different image - the whole idea behind the parallel universe from a physics standpoint is very well represented by this image. Nicely done.</td>', 'Very different image - the whole idea behind the parallel universe from a physics standpoint is very well represented by this image. Nicely done.', '2016-09-20 16:53:11.000000', NULL, 1),
(7474778, 1187614, 101256, '<td valign="top">I''ve changed this from a 9 to a 10. I like the grain and HDR effect. Additionally the figured swirls which permeate the image are very interesting - very clever processing.</td>', 'I''ve changed this from a 9 to a 10. I like the grain and HDR effect. Additionally the figured swirls which permeate the image are very interesting - very clever processing.', '2016-09-20 16:55:06.000000', NULL, 1),
