(7474780, 1187612, 101256, '<td valign="top">I gave this a 9 originally and it another one I stand by. I do feel that there had to be a way to lighten up the image slightly to bring out some more detail</td>', 'I gave this a 9 originally and it another one I stand by. I do feel that there had to be a way to lighten up the image slightly to bring out some more detail', '2016-09-20 16:58:06.000000', NULL, 1),
(7474781, 1187291, 101256, '<td valign="top">I''ve seen a lot of pictures of Rockport over the years - even have taken my fair share, but this is the first time I''ve seen something like this. Nice out of the box thinking and capture.</td>', 'I''ve seen a lot of pictures of Rockport over the years - even have taken my fair share, but this is the first time I''ve seen something like this. Nice out of the box thinking and capture.', '2016-09-20 16:58:19.000000', NULL, 1),
